TLM.f("Sancti/03-25",{"officium":"In Annuntiatione Beate Mariæ Virgine","rule":["ex C11;","Gloria","Credo","Prefatio=Maria=Annuntiatióne"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"Graduale":"Commune/C11"},"sections":{"Introitus":[{"k":"ref","la":"Ps 44:13; 44:15; 44:16"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: adducéntur Regi Vírgines post eam: próximæ ejus adducéntur tibi in lætítia et exsultatióne."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: adducéntur Regi Vírgines post eam: próximæ ejus adducéntur tibi in lætítia et exsultatióne."}],"Oratio":[{"k":"text","la":"Deus, qui de beátæ Maríæ Vírginis útero Verbum tuum, Angelo nuntiánte, carnem suscípere voluísti: præsta supplícibus tuis; ut, qui vere eam Genetrícem Dei crédimus, ejus apud te intercessiónibus adjuvémur."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ"},{"k":"ref","la":"Is 7:10-15"},{"k":"text","la":"In diébus illis: Locútus est Dóminus ad Achaz, dicens: Pete tibi signum a Dómino, Deo tuo, in profúndum inférni, sive in excélsum supra. Et dixit Achaz: Non petam et non tentábo Dóminum. Et dixit: Audíte ergo, domus David: Numquid parum vobis est, moléstos esse homínibus, quia molesti estis et Deo meo ? Propter hoc dabit Dóminus ipse vobis signum. Ecce, Virgo concípiet et páriet fílium, et vocábitur nomen ejus Emmánuel. Butýrum et mel cómedet, ut sciat reprobare malum et elígere bonum."}],"Graduale":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Post partum, Virgo, invioláta permansísti: Dei Génetrix, intercéde pro nobis. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."},{"k":"ref","la":"Num 17, 8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 44:3 et 5"},{"k":"text","la":"Diffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 44:11 et 12"},{"k":"text","la":"Audi, fília, et vide, et inclína aurem tuam: quia concupívit Rex spéciem tuam."},{"k":"ref","la":"Ps 44:13 et 10"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: fíliæ regum in honóre tuo."},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi."},{"k":"text","la":"Adducéntur in lætítia et exsultatióne: adducéntur in templum Regis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 1:26-38"},{"k":"text","la":"In illo témpore: Missus est Angelus Gábriël a Deo in civitátem Galilaéæ, cui nomen Názareth, ad Vírginem desponsátam viro, cui nomen erat Joseph, de domo David, et nomen Vírginis María. Et ingréssus Angelus ad eam, dixit: Ave, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Quæ cum audísset, turbáta est in sermóne ejus: et cogitábat, qualis esset ista salutátio. Et ait Angelus ei: Ne tímeas, María, invenísti enim grátiam apud Deum: ecce, concípies in útero et páries fílium, et vocábis nomen ejus Jesum. Hic erit magnus, et Fílius Altíssimi vocábitur, et dabit illi Dóminus Deus sedem David, patris ejus: et regnábit in domo Jacob in ætérnum, et regni ejus non erit finis. Dixit autem María ad Angelum: Quómodo fiet istud, quóniam virum non cognósco? Et respóndens Angelus, dixit ei: Spíritus Sanctus supervéniet in te, et virtus Altíssimi obumbrábit tibi. Ideóque et quod nascétur ex te Sanctum, vocábitur Fílius Dei. Et ecce, Elísabeth, cognáta tua, et ipsa concépit fílium in senectúte sua: et hic mensis sextus est illi, quæ vocátur stérilis: quia non erit impossíbile apud Deum omne verbum. Dixit autem María: Ecce ancílla Dómini, fiat mihi secúndum verbum tuum."}],"Offertorium":[{"k":"ref","la":"Luc 1:28 1:42"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus, et benedíctus fructus ventris tui."}],"Secreta":[{"k":"text","la":"In méntibus nostris, quǽsumus, Dómine, veræ fídei sacraménta confírma: ut, qui concéptum de Vírgine Deum verum et hóminem confitémur; per ejus salutíferæ resurrectiónis poténtiam, ad ætérnam mereámur perveníre lætítiam."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Is 7:14"},{"k":"text","la":"Ecce, Virgo concípiet et páriet fílium: et vocábitur nomen ejus Emmánuel."}],"Postcommunio":[{"k":"text","la":"Grátiam tuam, quǽsumus, Dómine, méntibus nostris infúnde: ut qui, Angelo nuntiánte, Christi Fílii tui incarnatiónem cognóvimus; per passiónem ejus et crucem, ad resurrectiónis glóriam perducámur."},{"k":"macro","name":"Per eundem"}]},"hr":{"92898c593a318cb8":{"t":"Ps 44, 13 i 15 i 16, Ps 44, 2\n(Ps 44, 13 et 15 et 16) Za pogledom tvojeg lica vapit će svi velikani. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti i veselju. (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam svoja djela Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 44, 13 et 15 et 16) Za pogledom tvojeg lica vapit će svi velikani. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti i veselju."},"650f7f180ffd4eba":{"t":"<i>Pomolimo se</i>.\nBože, koji si htio da po anđelovu navještenju tvoja Riječ uzme tijelo u krilu blažene Djevice Marije, daj, smjerno te molimo, da mi koji je priznajemo Bogorodicom, po njezinu zagovoru nađemo pomoć u tebe.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si htio, da po anđelovu naviještenju Riječ Tvoja uzme tijelo u krilu blažene Djevice Marije, daj, molimo Te, da njezinim zagovorom nađemo pomoć u Tebe, koji vjerujemo, da je ona doista Bogorodica. Po istom G. n. I. K.","knRef":"Kniewald 1942, str. 36–37 (snimka 19) (OCR)"},"01070ac82bdfed7f":{"t":"Iz 7, 10-15\nČitanje Izaije proroka. U one dane reče Gospodin Ahazu: Traži od Gospodina, Boga svojega, znak dolje u dubini ili gore u visini. Ahaz odgovori: Neću tražiti i neću iskušavati Gospodina. Tada reče (Izaija): Čujte sada, dome Davidov: Zar vam je malo, što ste teški ljudima, pa još odbijate i moga Boga? Zato će vam sam Gospodin dati znak: Evo, djevica će začeti i roditi sina i dat će mu ime Emanuel. On će se hraniti medom i mlijekom, dok ne sazna odbacivati zlo, a odabirati dobro.","kn":"Čitanje proroka Izaije (7, 10-15). U one dane reče Gospodin Ahazu: Traži od Gospodina svoga Boga znak za sebe, ili odozdo iz ponora ili odozgo s visine. Ahaz odgovori: Ne ću tražiti niti ću kušati Gospodina. Nato reče: Čujte vi iz kuće Davidove: Zar vam je malo, što dosađujete ljudima, pa dosađujete i momu Bogu? Zato će vam sam Gospodin dati znak; Evo, djevica će začeti i roditi sina i dat će mu ime Emanuel.^ Jesti će maslo 1 med, da zna odbaciti zlo, a izabrati dobro.","knRef":"Kniewald 1942, str. 532–533 (snimka 267) (OCR)"},"2c5d13324228e762":{"t":"Ps 44, 3 i 5\nMilina se razlila na tvojim usnama, stoga te je Bog blagoslovio u vijeke. Zbog vjernosti, blagosti i pravednosti divno će te voditi tvoja desnica.\n\nPs 44, 11 i 12, Ps 44, 13 i 10, Ps 44, 15-16\nČuj, kćeri, i pogledaj i prikloni svoje uho, jer je Kralj zavolio tvoju ljepotu. Za pogledom tvojeg lica vapit će svi velikani, kraljevske će ti kćeri biti u pratnji. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi. Poći će u radosti i veselju, poći će u hram Kraljev.","kn":"(Ps. 44, 3, 4). Tvojim se usnama razlio blagoslov, jer te Bog blagoslovio blagoslovom t vječnim. Poradi istine i pravde i blagosti vodit će te divno desnica tvoja.\n\n(Ps. 44, 12). Za ljepotom tvojom teži kralj, tvoj Gospodin. Cuj, kćeri, i vidi i sagni uho svoje. Aleluja, aleluja. Ovo je mudra djevica, aleluja. (Ps. 44, 12). Za Ijeipotom tvojom teži kralj, tvoj Gospodin. (Ps. 44, 13, 10) Najmoćniji ove žemlje slavit će tebe, pratit će te kćeri kraljevske. (Ps. 44, 15, 16) Prate je djevice i vode je kralju, prijateljice se okupljaju oko nje. Vode je u radosti i veselju, vode je u hram Kraljev.","knRef":"Kniewald 1942, str. 532–533 (snimka 267) (OCR)"},"b7fcb7fcf7056bff":{"t":"Lk 1, 26-38\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Posla Bog anđela Gabrijela u galilejski grad Nazaret k djevici Mariji, koja je bila zaručena s Davidovim potomkom Josipom. Anđeo uđe k njoj i reče: Zdravo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama! Kad je ona to čula, uplaši se i razmišljala je što taj pozdrav znači. Anđeo joj reče: Nemoj se bojati, Marijo, jer si našla milost u Boga: Evo, začet ćeš i roditi sina i dat ćeš mu ime Isus. On će biti velik i zvat će se Sin Svevišnjega. Gospodin će mu dati prijestolje njegova oca Davida, i vladat će Jakovljevom kućom dovijeka i njegovu kraljevstvu neće biti svršetka. Marija reče anđelu: Kako će to biti kad ne poznam muža? Anđeo joj odgovori: Duh će Sveti sići na te i sila će te Svevišnjega osjeniti. Zato će se ono Sveto, što ćeš ti roditi, zvati Sin Božji. A evo, i Elizabeta, tvoja rođakinja, i ona je začela sina u svojoj starosti, i njoj koju zovu nerotkinjom ovo je šesti mjesec, jer u Boga nije ništa nemoguće. Marija na to reče: Evo službenice Gospodnje, neka mi bude po riječi tvojoj.","kn":"t Slijedi sveto evanđelje po Luki (1, 26-38). U ono vrijeme posla Bog anđela Gabrijela u galilejski grad Nazaret k djevici zaručenoj s mužem, koji se zvaO' Josip iz kuće Davidove, a djevica se zvala Marija. Kad je anđeo k njoj ušao, reče: Zdravo milosti puna. Gospodin s tobom, blagoslovljena ti među ženama! Kad je ona to čula, uplaši se na ove riječi i razmišljala je, što znači taj pozdrav. A anđeo joj reče; Ne boj se, Marijo, jer si našla milost kod Bega: Evo, začet ćeš i roditi sina i dat ćeš mu ime Isus. On će biti velik i zvat će se Sin Svevišnjega. I Gospodin Bog dat će mu prijestolje Davida, njegova oca, i vladat će nad Jakovljevim domom u vijeke, i njegovu kraljevstvu ne će biti kraja. Marija upita anđela: Kako će to biti, kad ja ne (poznam muža? Anđeo joj odgovori: Duh Sveti doći će nad tebe i osjenit će te sila Svevišnjega; zato će i Sveto, koje ćeš ti roditi, biti Sin Božji. I tvoja je rođakinja Elizabeta začela Sv. Ivan Damascenski 27. III. sina u svojoj starosti, i njoj, koja je nerotkinja, ovo je šesti mjesec; jer Bogu nije ništa nemoguće. Na to Marija reče: Evo službenice Gospodnje, neka mi bude po tvojoj riječi.","knRef":"Kniewald 1942, str. 534–535 (snimka 268) (OCR)"},"9f99f01cc37689c1":{"t":"Lk 1, 28 i 42\nZdravo, Marijo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama i blagoslovljen plod utrobe tvoje.","kn":"(Lk. 1, 28). Zdravo Marijo, milosti puna, Gospodin s Tobom, blagoslovena Ti među ženama, blagosloven plod utrobe Tvoje.","knRef":"Kniewald 1942, str. 38–39 (snimka 20) (OCR)"},"36ce31aa57a7f6c9":{"t":"Molimo, Gospodine, učvrsti u našim dušama tajnu prave vjere, i daj nama, koji od Djevice Začetoga priznajemo pravim Bogom i čovjekom, da snagom njegova uskrsnuća zaslužimo doći u vječno veselje.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"2. (O BI. Djevici Mariji). Molimo, Gospodine, utvrdi otajstva prave vjere u našim, dušama, da mi, koji od Djevice Začetoga ispovijedamo pravim Bogom i čovjekom, snagom njegova spasonosnog uskrsnuća zaslužimo doći u vječno veselje.","knRef":"Kniewald 1942, str. 850–851 (snimka 426) (OCR)"},"c2c5418c31f4ac0d":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i> o naviještenju</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"11efe5bb9752667a":{"t":"Iz 7, 14\nEvo, Djevica će začeti i roditi Sina, i on će se zvati Emanuel.","kn":"(Izal. 7, 14). Evo, Djevica će začeti i rodit će Sina i zvat će se ime njegovo Emanuel.","knRef":"Kniewald 1942, str. 534–535 (snimka 268) (OCR)"},"db143b816c0c9ac5":{"t":"<i>Pomolimo se</i>.\nMilost svoju, molimo, Gospodine, ulij u naše duše, da mi, koji smo po anđelovu navješetenju spoznali utjelovljenje Krista Sina tvoga, po njegovoj muci i križu budemo privedeni k slavnom uskrsnuću.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, ulij u naše duše svoju milost, da mi, koji smo po anđelovu navlještenju spoznali utjelovljenje Krista, Sina Tvoga, ip.o njegovoj muci i križu budemo privedeni k slavi uskrsnuća, po istom G. n. I. K.","knRef":"Kniewald 1942, str. 534–535 (snimka 268) (OCR)"},"bc828de9b1933ad8":{"t":"Ps 44, 13 i 15 i 16, Ps 44, 2\n(Ps 44, 13 et 15 et 16) Za pogledom tvojeg lica vapit će svi velikani. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti i veselju. <i>Aleluja</i>, <i>aleluja</i>.\n(Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam svoja djela Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 44, 13 et 15 et 16) Za pogledom tvojeg lica vapit će svi velikani. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti i veselju. <i>Aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 44, 13, 15, 16). Najmoćniji ove zemlje slavit će tebe; prate je djevice i vode je kralju u radosti i veselju (Aleluja, aleluja). (Ps. 44, 2) Iz mog srca izvire divna pjesma: djela su moja namijenjena Kralju! Slava Ocu. Najmoćniji. -","knRef":"Kniewald 1942, str. 532–533 (snimka 267) (OCR)"},"9d41a9bb7feb1ac3":{"t":"Lk 1, 28\n<i>Aleluja</i>, <i>aleluja</i>.\n(Lk 1, 28) Zdravo Marijo, milosti puna. Gospodin s tobom, blagoslovljena ti među ženama. <i>Aleluja</i>.\nProcvala je mladica Jesejeva; Djevica je rodila Boga i čovjeka. Bog je vratio mir, u sebi pomirivši najniže s najvišim. <i>Aleluja</i>.","kn":"Aleluja, aleluja (Br. 17, 18). Procvalo je Jesejevo žezlo; djevica je rodila Boga i čovjeka. Bog^ je vratio mir, u sebi pomirivši najniže s najvišim. Aleluja (Lk. 1, 28.) Zdravo Marijo, milosti puna. Gospodin s Tobom, blagoslovljena ti među ženama, aleluja.","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"}}});
